import{_ as n,o as a,c as i,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Maven依赖机制浅析","description":"","frontmatter":{"title":"Maven依赖机制浅析","date":"2022-04-22","categories":["开发工具","构建工具"],"tags":["Java","Maven"]},"headers":[],"relativePath":"开发工具/Maven依赖机制浅析.md","filePath":"开发工具/Maven依赖机制浅析.md"}'),t={name:"开发工具/Maven依赖机制浅析.md"};function p(l,s,h,k,d,E){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="maven依赖机制浅析" tabindex="-1">Maven依赖机制浅析 <a class="header-anchor" href="#maven依赖机制浅析" aria-label="Permalink to &quot;Maven依赖机制浅析&quot;">​</a></h1><p>Maven通过pom文件来管理Java包的依赖关系，多个pom文件组合在一起可以理解为一颗抽象的依赖树，父节点或祖父节点的包会传递给子节点或祖孙节点，这被称作<strong>传递依赖</strong>(Transitive-Dependencies)。</p><p>传递依赖一般通过两个标签来实现：parent与dependency，其中，parent定义了上级依赖，dependency定义了下级依赖。</p><p>随着项目复杂性的提升，依赖树中包发生冲突的概率也会增加，Maven通过<strong>依赖仲裁</strong>(Dependency-Mediation)与<strong>依赖管理</strong>(Dependency-Management)来唯一确定依赖树中包的版本。</p><h2 id="一依赖仲裁" tabindex="-1">一、依赖仲裁 <a class="header-anchor" href="#一依赖仲裁" aria-label="Permalink to &quot;一、依赖仲裁&quot;">​</a></h2><blockquote><p>Maven使用dependencies标签来引入<strong>使用</strong>包。</p></blockquote><p>依赖仲裁，简而言之，就是在依赖树中包的版本发生冲突时，选择哪一个包的过程，Maven采取<strong>就近原则</strong>，即：</p><ol><li><strong>首先选择依赖层级最浅的</strong></li><li><strong>若依赖层次一致，则选择最先定义的</strong></li></ol><p>如对于以下依赖树：（参见<a href="https://maven.apache.org/guides/introduction/introduction-to-dependency-mechanism.html#Transitive_Dependencies" target="_blank" rel="noreferrer">官网</a>）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  A</span></span>
<span class="line"><span>  ├─ B</span></span>
<span class="line"><span>  │  └─ C</span></span>
<span class="line"><span>  │      └─ D（2.0）</span></span>
<span class="line"><span>  └─ E</span></span>
<span class="line"><span>      └─ D（1.0）</span></span></code></pre></div><p>D包有两个版本，其对应了两条依赖路径：A --&gt; B --&gt; C --&gt; D 与 A --&gt; E --&gt; D，第二条路径最短（依赖层级最浅），符合上述<strong>就近原则</strong>的第一条规则，最终选择D包的1.0版本。</p><p>又如，对于以下依赖树：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  A</span></span>
<span class="line"><span>  ├─ B</span></span>
<span class="line"><span>  │  └─ D（2.0）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ C</span></span>
<span class="line"><span>  │  └─ D（1.0）</span></span></code></pre></div><p>D同样有两个版本，他们的依赖层级一样，A --&gt; B --&gt; D路径上的D最先定义，符合上述<strong>就近原则</strong>的第二条规则，最终选择D包的2.0版本。</p><p>如果想要某个包的版本优先使用，可以将节点提到上级pom节点（满足依赖层级最浅的规则），也可以将对应节点交换位置（满足最先定义的规则）。</p><p>当然，还有另外一种方法，那就是<strong>依赖管理</strong>。</p><h2 id="二依赖管理" tabindex="-1">二、依赖管理 <a class="header-anchor" href="#二依赖管理" aria-label="Permalink to &quot;二、依赖管理&quot;">​</a></h2><blockquote><p>Maven使用dependencyManagement标签来<strong>定义</strong>包。</p></blockquote><p>与dependencies不同的地方在于，dependencyManagement中的包只是一个定义，只有在dependencies中引入对应包时，dependencyManagement中的定义才有意义。</p><p>凡是在dependencyManagement中定义的包，dependencies中引入对应包时，都可以省略版本号，Maven会自动从dependencyManagement中找到对应版本，这一特性为包的版本统一提供了极大的便利性。</p><p>同时，有一点需要非常注意：<strong>在子模块中，dependencies中包的版本无法覆盖dependencyManagement中对应包的版本</strong>，如下所示：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;com.squareup.okhttp3&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;okhttp&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;4.9.3&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencyManagement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;com.squareup.okhttp3&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;okhttp&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;3.8.1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencyManagement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>在上述pom中dependencies与dependencyManagement使用了okhttp，但它们的版本不一样，此时，Maven将优先使用在dependencyManagement中定义的3.8.1版本，因为在Maven中，<strong>依赖管理优先于依赖仲裁</strong> ，即使是在父节点（根节点除外）的dependencies引入一个层级更浅的okhttp版本，这里依旧会取dependencyManagement中okhttp的版本，因为不管okhttp位于哪个节点（根节点除外），它都是处于依赖仲裁的范围内，它的优先级永远低于依赖管理。</p><p>同时，顶层根节点（如启动类所在的web节点）的优先级最高。</p><p>因此，在Maven依赖中存在以下优先级：</p><p><strong>顶层根节点引入的依赖</strong> &gt; <strong>依赖管理</strong> &gt; <strong>依赖仲裁</strong></p><h2 id="三总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><p>至此，对于如何唯一确定一个包，并解决包冲突，我们也有了明确的方向：</p><ol><li>根据依赖管理原则，在dependencyManagement中寻找包的版本</li><li>根据依赖仲裁原则，在dependencies中寻找包的版本</li><li>在顶层根节点寻找包的版本</li><li>按照上述 <code>顶层根节点引入的依赖 &gt; 依赖管理 &gt; 依赖仲裁</code> 找到合适的包版本</li></ol><blockquote><p>参考文档</p></blockquote><ol><li><a href="https://maven.apache.org/guides/introduction/introduction-to-dependency-mechanism.html" target="_blank" rel="noreferrer">Maven Dependency Mechanism</a></li></ol>`,31)])])}const o=n(t,[["render",p]]);export{g as __pageData,o as default};
